-- Make billing.tax_enabled / billing.tax_rate authoritative for customer checkout.
-- Tax is calculated after discounts and persisted on both the invoice and order.

CREATE OR REPLACE FUNCTION public.cart_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare uid uuid:=auth.uid(); cid uuid; subtotal bigint:=0; discount bigint:=0; eligible bigint:=0; tax bigint:=0; taxable bigint:=0; tax_enabled boolean:=false; tax_rate numeric:=0; c public.coupons%rowtype; used_count integer; items jsonb:='[]'::jsonb; r record; line bigint; coupon text;
begin
 if uid is null then raise exception 'authentication required'; end if;
 cid:=public.get_or_create_cart(); select coupon_code into coupon from public.shopping_carts where id=cid;
 for r in select i.*,p.name,p.slug,p.price_cents,p.currency,p.metadata,p.license_product_key from public.shopping_cart_items i join public.products p on p.id=i.product_id where i.cart_id=cid order by case when public.canonical_license_component_key(p.license_product_key)='orbitfs_base' then 0 else 1 end,p.name loop
   line:=coalesce(r.price_cents,0)*r.quantity; subtotal:=subtotal+line;
   items:=items||jsonb_build_array(jsonb_build_object('id',r.id,'product_id',r.product_id,'name',r.name,'slug',r.slug,'quantity',r.quantity,'configuration',r.configuration,'line_total_cents',line,'currency',r.currency,'license_product_key',public.canonical_license_component_key(r.license_product_key)));
 end loop;
 if coalesce((select (value#>>'{}')::boolean from public.app_settings where key='products.allow_coupons'),true)=false then coupon:=null; end if;
 if coupon is not null and subtotal>0 then
   select * into c from public.coupons where lower(code)=lower(coupon) and active=true and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now()) and subtotal>=min_order_cents;
   if found then
     select coalesce(sum(coalesce(p.price_cents,0)*i.quantity),0) into eligible from public.shopping_cart_items i join public.products p on p.id=i.product_id where i.cart_id=cid and (cardinality(c.product_ids)=0 or p.id=any(c.product_ids));
     select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id; if c.max_redemptions is not null and used_count>=c.max_redemptions then raise exception 'coupon redemption limit reached'; end if;
     select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id and auth_user_id=uid; if used_count>=c.per_user_limit then raise exception 'coupon already used'; end if;
     if eligible<=0 then raise exception 'coupon does not apply to products in this basket'; end if;
     if c.discount_type='percent' then discount:=least(eligible,round(eligible*(c.discount_value::numeric/100))); else discount:=least(eligible,c.discount_value); end if;
   else raise exception 'invalid or unavailable coupon'; end if;
 end if;
 taxable:=greatest(0,subtotal-discount);
 select coalesce((value#>>'{}')::boolean,false) into tax_enabled from public.app_settings where key='billing.tax_enabled';
 select coalesce((value#>>'{}')::numeric,0) into tax_rate from public.app_settings where key='billing.tax_rate';
 if coalesce(tax_enabled,false) and tax_rate>0 then tax:=round(taxable*(tax_rate/100)); end if;
 return jsonb_build_object('cart_id',cid,'items',items,'subtotal_cents',subtotal,'discount_cents',discount,'tax_cents',tax,'total_cents',taxable+tax,'coupon_code',coupon,'item_count',jsonb_array_length(items));
end $$;


CREATE OR REPLACE FUNCTION public.checkout_cart(p_pay_with_credit boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare uid uuid:=auth.uid(); cid uuid; sumry jsonb; subtotal bigint; discount bigint; tax bigint:=0; total bigint; cust uuid; ord uuid; inv uuid; ordno text; invno text; order_prefix text:='ORB-'; invoice_prefix text:='INV-'; due_days integer:=7; r record; oi uuid; c public.coupons%rowtype; coupon text; has_base boolean; payres jsonb; currency_code text; currency_count integer; is_gift boolean; gift_email text;
begin
 if uid is null then raise exception 'authentication required'; end if; if not public.account_can_order(uid) then raise exception 'account is not allowed to place new orders'; end if;
 cid:=public.get_or_create_cart(); if not exists(select 1 from public.shopping_cart_items where cart_id=cid) then raise exception 'basket is empty'; end if;
 select count(distinct p.currency),min(p.currency) into currency_count,currency_code from public.shopping_cart_items i join public.products p on p.id=i.product_id where i.cart_id=cid; if currency_count>1 then raise exception 'basket contains products in multiple currencies'; end if; if currency_code is null then raise exception 'basket currency unavailable'; end if;
 has_base:=exists(select 1 from public.products p join public.shopping_cart_items i on i.product_id=p.id where i.cart_id=cid and p.license_product_key in ('orbitfs_panel','orbitfs_base') and not coalesce((i.configuration->>'gift')::boolean,false)) or exists(select 1 from public.products p where p.license_product_key in ('orbitfs_panel','orbitfs_base') and public.user_has_active_product(uid,p.id));
 for r in select i.*,p.name,p.slug,p.price_cents,p.currency,p.metadata,p.license_product_key from public.shopping_cart_items i join public.products p on p.id=i.product_id where i.cart_id=cid loop
  is_gift:=coalesce((r.configuration->>'gift')::boolean,false);
  gift_email:=lower(trim(coalesce(r.configuration->>'gift_recipient_email','')));
  if is_gift then
    if gift_email='' or gift_email !~* '^[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}$' then raise exception 'enter a valid gift recipient email for %',r.name; end if;
  else
    if not coalesce((r.metadata->>'allow_repeat_purchase')::boolean,false) and public.user_has_active_product(uid,r.product_id) then raise exception 'you already own active product %',r.name; end if;
    if r.license_product_key not in ('orbitfs_panel','orbitfs_base') and not has_base then raise exception '% requires OrbitFS Base. Add Base to the basket or activate an existing Base service first.',r.name; end if;
    if exists(select 1 from public.invoices x join public.order_items xoi on xoi.order_id=x.order_id where x.auth_user_id=uid and xoi.product_id=r.product_id and x.status in ('unpaid','partial','overdue')) then raise exception 'an unpaid invoice already exists for %',r.name; end if;
  end if;
 end loop;
 sumry:=public.cart_summary(); subtotal:=(sumry->>'subtotal_cents')::bigint; discount:=(sumry->>'discount_cents')::bigint; tax:=coalesce((sumry->>'tax_cents')::bigint,0); total:=(sumry->>'total_cents')::bigint; coupon:=sumry->>'coupon_code';
 select coalesce((select (value#>>'{}')::int from public.app_settings where key='invoice.due_days'),7) into due_days; select coalesce((select trim(both '\"' from value::text) from public.app_settings where key='billing.order_prefix'),'ORB-') into order_prefix; select coalesce((select trim(both '\"' from value::text) from public.app_settings where key='invoice.prefix'),'INV-') into invoice_prefix; select id into cust from public.customers where auth_user_id=uid limit 1;
 ordno:=order_prefix||lpad(nextval('public.order_number_seq')::text,6,'0'); insert into public.orders(order_number,customer_id,auth_user_id,status,payment_status,fulfillment_status,subtotal_cents,tax_cents,total_cents,currency,metadata) values(ordno,cust,uid,case when total=0 then 'active' else 'pending_payment' end,case when total=0 then 'paid_free' else 'unpaid' end,'pending',subtotal,tax,total,currency_code,jsonb_build_object('basket_checkout',true,'coupon_code',coupon,'contains_gifts',exists(select 1 from public.shopping_cart_items i where i.cart_id=cid and coalesce((i.configuration->>'gift')::boolean,false)))) returning id into ord;
 invno:=invoice_prefix||lpad(nextval('public.invoice_number_seq')::text,6,'0'); insert into public.invoices(invoice_number,order_id,auth_user_id,status,subtotal_cents,discount_cents,tax_cents,total_cents,paid_cents,currency,due_at,paid_at) values(invno,ord,uid,case when total=0 then 'paid' else 'unpaid' end,subtotal,discount,tax,total,0,currency_code,case when total=0 then now() else now()+make_interval(days=>due_days) end,case when total=0 then now() else null end) returning id into inv;
 for r in select i.*,p.name,p.slug,p.price_cents,p.license_product_key from public.shopping_cart_items i join public.products p on p.id=i.product_id where i.cart_id=cid order by case when p.license_product_key in ('orbitfs_panel','orbitfs_base') then 0 else 1 end,p.name loop
   insert into public.order_items(order_id,product_id,product_name,product_slug,license_product_key,quantity,unit_price_cents,total_cents,configuration,service_status) values(ord,r.product_id,r.name,r.slug,r.license_product_key,r.quantity,coalesce(r.price_cents,0),coalesce(r.price_cents,0)*r.quantity,r.configuration,case when coalesce((r.configuration->>'gift')::boolean,false) then 'pending_gift' else 'pending' end) returning id into oi;
   insert into public.invoice_items(invoice_id,order_item_id,description,quantity,unit_price_cents,total_cents) values(inv,oi,r.name,r.quantity,coalesce(r.price_cents,0),coalesce(r.price_cents,0)*r.quantity);
   if coalesce((r.configuration->>'gift')::boolean,false) then
     insert into public.gift_deliveries(source_order_id,source_order_item_id,purchaser_user_id,recipient_email,status,metadata) values(ord,oi,uid,lower(trim(r.configuration->>'gift_recipient_email')),'pending',jsonb_build_object('product_id',r.product_id,'product_name',r.name)) on conflict(source_order_item_id) do nothing;
   end if;
 end loop;
 if coupon is not null then select * into c from public.coupons where lower(code)=lower(coupon) limit 1; if c.id is not null then insert into public.coupon_redemptions(coupon_id,invoice_id,auth_user_id,discount_cents) values(c.id,inv,uid,discount); end if; end if;
 delete from public.shopping_cart_items where cart_id=cid; update public.shopping_carts set coupon_code=null,updated_at=now() where id=cid;
 if total=0 then perform public.grant_paid_order_entitlements(ord,uid); elsif p_pay_with_credit or coalesce((select (value#>>'{}')::boolean from public.app_settings where key='billing.auto_apply_credit'),false) then payres:=public.pay_invoice_with_credit(inv); end if;
 return jsonb_build_object('order_id',ord,'order_number',ordno,'invoice_id',inv,'invoice_number',invno,'subtotal_cents',subtotal,'discount_cents',discount,'tax_cents',tax,'total_cents',total,'currency',currency_code,'paid',total=0 or coalesce(payres->>'status','')='paid','contains_gifts',exists(select 1 from public.gift_deliveries where source_order_id=ord));
end $_$;


CREATE OR REPLACE FUNCTION public.create_order_invoice(p_product_id uuid, p_configuration jsonb DEFAULT '{}'::jsonb, p_coupon_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ declare uid uuid:=auth.uid(); prod public.products%rowtype; cust uuid; ord uuid; item uuid; inv uuid; invno text; ordno text; subtotal bigint; option_total bigint:=0; discount bigint:=0; tax bigint:=0; total bigint; tax_enabled boolean:=false; tax_rate numeric:=0; c public.coupons%rowtype; used_count integer; dep record; opt record; selected text; choice jsonb; due_days integer:=7; order_prefix text:='ORB-'; invoice_prefix text:='INV-'; allow_repeat boolean:=false; is_free boolean:=false; begin if uid is null then raise exception 'authentication required'; end if; if not public.account_can_order(uid) then raise exception 'account is not allowed to place new orders'; end if; select * into prod from public.products where id=p_product_id and active=true; if not found then raise exception 'product unavailable'; end if; allow_repeat:=coalesce((prod.metadata->>'allow_repeat_purchase')::boolean,false); is_free:=coalesce((prod.metadata->>'free_product')::boolean,false); if prod.price_cents is null and not is_free then raise exception 'product pricing has not been configured'; end if; if not allow_repeat and exists(select 1 from public.download_entitlements de where de.auth_user_id=uid and de.product_id=prod.id and de.status='active') then raise exception 'you already own this product'; end if; if exists(select 1 from public.invoices i join public.order_items oi on oi.order_id=i.order_id where i.auth_user_id=uid and oi.product_id=prod.id and i.status in ('unpaid','partial','overdue')) then raise exception 'an unpaid invoice already exists for this product'; end if; for dep in select pd.requires_product_id,p.name from public.product_dependencies pd join public.products p on p.id=pd.requires_product_id where pd.product_id=prod.id loop if not exists(select 1 from public.download_entitlements de where de.auth_user_id=uid and de.product_id=dep.requires_product_id and de.status='active') then raise exception 'This product requires an active % entitlement first',dep.name; end if; end loop; subtotal:=coalesce(prod.price_cents,0); for opt in select * from public.product_options where product_id=prod.id and active=true order by sort_order loop selected:=p_configuration->>opt.key; if opt.required and (selected is null or btrim(selected)='') then raise exception 'Required option missing: %',opt.label; end if; if selected is not null and btrim(selected)<>'' then if opt.option_type='select' and jsonb_array_length(opt.choices)>0 then select x into choice from jsonb_array_elements(opt.choices) x where (jsonb_typeof(x)='string' and trim(both '"' from x::text)=selected) or (jsonb_typeof(x)='object' and x->>'value'=selected) limit 1; if choice is null then raise exception 'Invalid choice for %',opt.label; end if; option_total:=option_total+coalesce(case when jsonb_typeof(choice)='object' then nullif(choice->>'price_delta_cents','')::bigint else null end,opt.price_delta_cents,0); else option_total:=option_total+coalesce(opt.price_delta_cents,0); end if; end if; end loop; subtotal:=subtotal+option_total; if p_coupon_code is not null and btrim(p_coupon_code)<>'' then select * into c from public.coupons where lower(code)=lower(btrim(p_coupon_code)) and active=true and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now()) and discount_type in ('percent','fixed') and subtotal>=min_order_cents and (cardinality(product_ids)=0 or prod.id=any(product_ids)); if not found then raise exception 'invalid or unavailable coupon'; end if; select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id; if c.max_redemptions is not null and used_count>=c.max_redemptions then raise exception 'coupon redemption limit reached'; end if; select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id and auth_user_id=uid; if used_count>=c.per_user_limit then raise exception 'coupon already used'; end if; if c.discount_type='percent' then discount:=least(subtotal,round(subtotal*(c.discount_value::numeric/100))); else discount:=least(subtotal,c.discount_value); end if; end if; total:=greatest(0,subtotal-discount); select coalesce((value#>>'{}')::boolean,false) into tax_enabled from public.app_settings where key='billing.tax_enabled'; select coalesce((value#>>'{}')::numeric,0) into tax_rate from public.app_settings where key='billing.tax_rate'; if coalesce(tax_enabled,false) and tax_rate>0 then tax:=round(total*(tax_rate/100)); total:=total+tax; end if; select coalesce((select (value#>>'{}')::int from public.app_settings where key='invoice.due_days'),7) into due_days; select coalesce((select trim(both '"' from value::text) from public.app_settings where key='billing.order_prefix'),'ORB-') into order_prefix; select coalesce((select trim(both '"' from value::text) from public.app_settings where key='invoice.prefix'),'INV-') into invoice_prefix; select id into cust from public.customers where auth_user_id=uid limit 1; ordno:=order_prefix||lpad(nextval('public.order_number_seq')::text,6,'0'); insert into public.orders(order_number,customer_id,auth_user_id,status,payment_status,fulfillment_status,subtotal_cents,tax_cents,total_cents,currency,metadata) values(ordno,cust,uid,case when total=0 then 'active' else 'pending_payment' end,case when total=0 then 'paid_free' else 'unpaid' end,'pending',subtotal,tax,total,prod.currency,jsonb_build_object('configuration',p_configuration,'option_total_cents',option_total)) returning id into ord; insert into public.order_items(order_id,product_id,product_name,product_slug,license_product_key,quantity,unit_price_cents,total_cents,configuration) values(ord,prod.id,prod.name,prod.slug,prod.license_product_key,1,subtotal,total,p_configuration) returning id into item; invno:=invoice_prefix||lpad(nextval('public.invoice_number_seq')::text,6,'0'); insert into public.invoices(invoice_number,order_id,auth_user_id,status,subtotal_cents,discount_cents,tax_cents,total_cents,paid_cents,currency,due_at,paid_at) values(invno,ord,uid,case when total=0 then 'paid' else 'unpaid' end,subtotal,discount,tax,total,case when total=0 then 0 else 0 end,prod.currency,case when total=0 then now() else now()+make_interval(days=>due_days) end,case when total=0 then now() else null end) returning id into inv; insert into public.invoice_items(invoice_id,order_item_id,description,quantity,unit_price_cents,total_cents) values(inv,item,prod.name,1,subtotal,total); if c.id is not null then insert into public.coupon_redemptions(coupon_id,invoice_id,auth_user_id,discount_cents) values(c.id,inv,uid,discount); end if; if total=0 then perform public.grant_paid_order_entitlements(ord,uid); end if; return jsonb_build_object('order_id',ord,'order_number',ordno,'invoice_id',inv,'invoice_number',invno,'total_cents',total,'discount_cents',discount,'tax_cents',tax,'option_total_cents',option_total,'paid',total=0); end $$;

